{#-
Last updated by Diego 04/14/2026. General Administrative information Template
To be reused (as a block) inside other templates so we do not repeat Twig
-#}

{#- ------ Macros Start ----- -#}

{%- macro html_output(html_title, source_datum, list_wrapper, markdown, rich) -%}
  {% set list_wrapper = list_wrapper|default("p") %}
  {% set markdown = markdown|default(false) %}
  {% set rich = rich|default(false) %}
  {# Handle Drupal-style objects with a "value" property #}


  {%- if source_datum is iterable and 'value' in source_datum|keys -%}
    {%- set source_datum = source_datum.value -%}
  {%- endif -%}
 
  {# -- Macro note: if markdown is selected no wrapper will be used -#}
  {%- if source_datum and source_datum|length > 0 -%}
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">
    {%- if html_title|length > 0 -%}
     <{{ list_wrapper }}>{{ html_title }}</{{ list_wrapper }}>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        {%- if markdown -%}
          {{ source_data|markdown_2_html }}
        {%- else -%}
          {%- if rich -%}
            <{{ list_wrapper }}>{{ source_data|raw }}</{{ list_wrapper }}>
          {%- else -%}
            <{{ list_wrapper }}>{{ source_data|striptags }}</{{ list_wrapper }}>
          {%- endif -%}
        {%- endif -%}
      {%- endfor -%}
    {%- else -%}
      {%- if markdown -%}
        {{ source_datum|markdown_2_html }}
      {%- else -%}
        {%- if rich -%}
          {%- if list_wrapper|length > 0 -%}
            <{{ list_wrapper }}>{{ source_datum|raw }}</{{ list_wrapper }}>
          {%- else -%}
            {{ source_datum|raw }}
          {%- endif -%}
          {%- else -%}
          <{{ list_wrapper }}>{{ source_datum|striptags }}</{{ list_wrapper }}>
        {%- endif -%}
      {%- endif -%}
    {%- endif -%}
      </div>
    </div>
  {%- endif -%}
   
{%- endmacro html_output -%}
{% if logged_in and ("administrator" in user_roles or "nypr_staff" in user_roles) and node.id is not empty %}
<div class="fs-6 bg-primary text-white rounded-2 px-3 py-1 mt-2 mb-2">Administrative Information</div> 
<p><i>The information shown after this point is only being display for Logged In Users.</i></p>
  {{ _self.html_output('Drupal Node ID', node.id, 'p') }}  
  {{ _self.html_output('Archipelago UUID',node.uuid.value,'p') }}  
<div>
  {% if data.local_identifiers|length > 0 %}
    {% set accumulated_local_identifiers = [] %}
    {% for local_identifier in data.local_identifiers %}
     {% set accumulated_local_identifiers = accumulated_local_identifiers|merge(['<span class="fw-bold">' ~ local_identifier.source ~ ' : </span> ' ~ local_identifier.value ]) %}
    {% endfor %}
    {% if accumulated_local_identifiers is iterable and not empty %}
      {{ _self.html_output("Local Identifiers", accumulated_local_identifiers,  list_wrapper = "p", markdown = false, rich = true) }}
    {% endif %}
  {% endif %}  
</div>
{{ _self.html_output('Note', data.note, 'p') }} 
{{ _self.html_output('Provenance', data.provenance, 'p') }} 
<div>
{% if data.annotations|length > 0 %}
  {% set accumulated_annotations = [] %}
  {% for annotations in data.annotations %}
    {% set accumulated_annotations = accumulated_annotations|merge([((annotations.type|length > 0) ? '<span class="fw-bold">' ~ annotations.type ~ ' : </span> ' : '' ) ~ annotations.value ]) %}
  {% endfor %}
  {% if accumulated_annotations is iterable and not empty %}
    {{ _self.html_output("Annotations", accumulated_annotations,  list_wrapper = "p", markdown = false, rich = true) }}
  {% endif %}
{% endif %} 
</div>
{{ _self.html_output('Minimum Viable Metadata', data.minimum_viable_metadata_present, 'p') }} 
{% endif %} {# end if logged_in #}
